<script setup lang="ts">import { ArrowLeft, Download } from 'lucide-vue-next'; const route=useRoute(); const {request,apiUrl}=useApi(); const {data:report,pending,error}=await useAsyncData(`report-${route.params.id}`,()=>request<any>(`/reports/${route.params.id}/public`)); function download(){window.open(apiUrl(`/reports/${route.params.id}/download`),'_blank','noopener,noreferrer')}</script>
<template><div class="page"><div class="container"><NuxtLink to="/fecoclima-ia/reportes" class="back"><ArrowLeft/>Volver a reportes</NuxtLink><ErrorState v-if="error"/><LoadingState v-else-if="pending"/><article v-else class="card"><div class="card-body"><div class="row-between"><div><h1 class="page-title">{{report.title}}</h1><p class="page-subtitle">{{report.date_from}} – {{report.date_to}}</p></div><button v-if="report.status==='COMPLETED'" class="btn btn-primary" @click="download"><Download/>Descargar PDF</button></div><hr class="divider"><dl><div><dt>Estado</dt><dd>{{report.status}}</dd></div><div><dt>Estación</dt><dd>{{report.station_name}}</dd></div><div><dt>Cultivo</dt><dd>{{report.crop_name}}</dd></div><div><dt>Regla</dt><dd>{{report.rule_version||'No disponible'}}</dd></div></dl><p v-if="report.error_message" class="notice notice-danger">{{report.error_message}}</p></div></article></div></div></template>
<style scoped>.back{display:inline-flex;align-items:center;gap:7px;min-height:44px;margin-bottom:18px;color:var(--fc-primary);font-weight:700}.back svg,.btn svg{width:18px}dl{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}dl>div{min-width:0;padding:12px;border-radius:10px;background:var(--fc-surface-muted)}dt{font-size:.78rem;color:var(--fc-text-muted)}dd{margin:5px 0 0;overflow-wrap:anywhere;font-weight:800;color:var(--fc-primary)}@media(max-width:720px){dl{grid-template-columns:1fr 1fr}.row-between .btn{width:100%}}@media(max-width:430px){dl{grid-template-columns:1fr}}</style>
